/**
 * Prism-Compatible Zero-Build Standalone Syntax Highlighter for Sawala Mono Showcase
 * CSP-compliant (script-src 'self', zero eval), preserves multi-char operator runs
 * so OpenType contextual alternates (calt) render intact across all browsers.
 */
(function (globalScope) {
	"use strict";

	const LANGUAGE_KEYWORDS = {
		typescript: new Set([
			"interface", "readonly", "const", "let", "var", "async", "await", "return",
			"function", "type", "export", "import", "from", "if", "else", "for", "while",
			"switch", "case", "break", "continue", "new", "throw", "try", "catch", "extends",
			"implements", "class", "public", "private", "protected"
		]),
		rust: new Set([
			"use", "crate", "pub", "fn", "let", "mut", "match", "if", "else", "for", "in",
			"while", "loop", "return", "struct", "enum", "impl", "trait", "where", "const",
			"static", "ref", "move", "async", "await", "Self", "self", "super"
		]),
		go: new Set([
			"package", "import", "func", "range", "for", "if", "else", "switch", "case",
			"default", "return", "struct", "interface", "type", "var", "const", "chan",
			"go", "defer", "select", "map", "make", "len"
		]),
		python: new Set([
			"from", "import", "class", "def", "if", "elif", "else", "for", "in", "while",
			"return", "and", "or", "not", "is", "None", "with", "as", "try", "except",
			"finally", "raise", "yield", "async", "await", "pass", "lambda"
		]),
		lua: new Set([
			"local", "function", "if", "then", "elseif", "else", "end", "for", "in", "do",
			"while", "repeat", "until", "return", "and", "or", "not", "nil", "tostring"
		]),
		json: new Set([]),
		toml: new Set([]),
		bash: new Set(["mkdir", "cp", "fc-cache", "sudo", "brew", "pacman", "git", "cd", "echo"]),
		conf: new Set(["font_family", "bold_font", "italic_font", "bold_italic_font", "font_size", "disable_ligatures"])
	};

	const LANGUAGE_TYPES = {
		typescript: new Set([
			"DeliberationSession", "ReadonlyArray", "Developer", "PullRequest", "Promise",
			"Result", "ReviewError", "boolean", "string", "number", "void", "Error"
		]),
		rust: new Set([
			"Deliberation", "QuorumState", "ReviewVerdict", "Result", "Ok", "Err",
			"Option", "Some", "None", "str", "usize", "u32", "u64", "bool", "String", "Vec"
		]),
		go: new Set([
			"PullRequest", "Verdict", "error", "bool", "string", "int", "uint", "byte"
		]),
		python: new Set([
			"dataclass", "SawalaMetrics", "int", "float", "bool", "str", "list", "dict"
		]),
		lua: new Set(["vim", "M"])
	};

	const BOOLEAN_LITERALS = new Set(["true", "false", "True", "False", "null", "nil", "None"]);

	const TOKEN_PATTERNS = {
		typescript: /\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|0x[0-9a-fA-F_]+|\b\d+(?:\.\d+)?\b|!==|===|<=>|\.\.\.|=>|->|<-|::|!=|==|<=|>=|\|>|&&|\|\||\+\+|--|[+\-*/%=<>!&|^~?:]+|\b[A-Za-z_][A-Za-z0-9_]*\b|[{}[\]().,;]/g,
		rust: /\/\/[^\n]*|\/\*[\s\S]*?\*\/|#!?\[[^\]]*\]|r(#*)"[\s\S]*?"\1|"(?:\\.|[^"\\])*"|'(?:[A-Za-z_][A-Za-z0-9_]*|\\.|[^'\\])'|0x[0-9a-fA-F_]+|\b\d+(?:\.\d+)?\b|\.\.=|\.\.|<=>|!==|===|=>|->|<-|::|!=|==|<=|>=|\|>|&&|\|\||[+\-*/%=<>!&|^~?:]+|\b[A-Za-z_][A-Za-z0-9_]*\b|[{}[\]().,;]/g,
		go: /\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|`[^`]*`|0x[0-9a-fA-F_]+|\b\d+(?:\.\d+)?\b|<-|:=|!=|==|<=|>=|&&|\|\||\+\+|--|[+\-*/%=<>!&|^~?:]+|\b[A-Za-z_][A-Za-z0-9_]*\b|[{}[\]().,;]/g,
		python: /#[^\n]*|"""[\s\S]*?"""|'''[\s\S]*?'''|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|@[A-Za-z_][A-Za-z0-9_]*|\b\d+(?:\.\d+)?\b|->|:=|!=|==|<=|>=|[+\-*/%=<>!&|^~?:]+|\b[A-Za-z_][A-Za-z0-9_]*\b|[{}[\]().,;]/g,
		lua: /--\[\[[\s\S]*?\]\]|--[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b\d+(?:\.\d+)?\b|~=|==|<=|>=|\.\.|->|[+\-*/%=<>#]+|\b[A-Za-z_][A-Za-z0-9_]*\b|[{}[\]().,;:]/g,
		json: /"(?:\\.|[^"\\])*"|\b\d+(?:\.\d+)?\b|\b(?:true|false|null)\b|[{}[\],:]/g,
		toml: /#[^\n]*|\[[^\]]+\]|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b\d+(?:\.\d+)?\b|\b(?:true|false)\b|[A-Za-z0-9_.-]+|[=[\],.]/g,
		conf: /#[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b\d+(?:\.\d+)?\b|\b(?:true|false)\b|[A-Za-z0-9_.-]+|[=]/g,
		default: /\/\/[^\n]*|#[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b\d+(?:\.\d+)?\b|!==|===|<=>|=>|->|<-|::|!=|==|<=|>=|\|>|[+\-*/%=<>!&|^~?:]+|\b[A-Za-z_][A-Za-z0-9_]*\b|[{}[\]().,;]/g
	};

	const HASH_COMMENT_LANGS = new Set(["python", "toml", "conf", "bash", "default"]);

	function escapeHtml(text) {
		return String(text)
			.replace(/&/g, "&amp;")
			.replace(/</g, "&lt;")
			.replace(/>/g, "&gt;");
	}

	function classifyMatch(token, lang, nextChar) {
		if (
			token.startsWith("//") ||
			token.startsWith("/*") ||
			token.startsWith("--") ||
			(token.startsWith("#") && HASH_COMMENT_LANGS.has(lang))
		) {
			return "comment";
		}

		if (lang === "rust" && (token.startsWith("#[") || token.startsWith("#!["))) {
			return "atrule";
		}

		if (lang === "toml" && token.startsWith("[")) {
			return "keyword";
		}

		if (
			token.startsWith("\"") ||
			token.startsWith("'") ||
			token.startsWith("`") ||
			(lang === "rust" && /^r#*"/.test(token))
		) {
			if (lang === "rust" && token.startsWith("'") && token.length > 2 && !token.endsWith("'")) {
				return "keyword";
			}
			return "string";
		}

		if (token.startsWith("@")) {
			return "function";
		}

		if (/^(?:0x[0-9a-fA-F_]+|\d+(?:\.\d+)?)$/.test(token)) {
			return "number";
		}

		if (BOOLEAN_LITERALS.has(token)) {
			return "boolean";
		}

		const keywords = LANGUAGE_KEYWORDS[lang] || new Set();
		if (keywords.has(token)) {
			return "keyword";
		}

		const types = LANGUAGE_TYPES[lang] || new Set();
		if (types.has(token)) {
			return "type";
		}

		if (/^[A-Za-z_][A-Za-z0-9_]*$/.test(token)) {
			if (nextChar === "(") {
				return "function";
			}
			return "variable";
		}

		if (/^[{}[\]().,;:]$/.test(token)) {
			return "punctuation";
		}

		return "operator";
	}

	function highlight(code, _grammar, language) {
		const lang = (language || "typescript").toLowerCase();
		const pattern = new RegExp((TOKEN_PATTERNS[lang] || TOKEN_PATTERNS.default).source, "g");
		const source = String(code || "");
		let lastIndex = 0;
		let output = "";
		let match = pattern.exec(source);

		while (match !== null) {
			const matchStart = match.index;
			const rawToken = match[0];

			if (matchStart > lastIndex) {
				output += escapeHtml(source.slice(lastIndex, matchStart));
			}

			const nextChar = source.charAt(matchStart + rawToken.length);
			const tokenClass = classifyMatch(rawToken, lang, nextChar);
			output += `<span class="token ${tokenClass}">${escapeHtml(rawToken)}</span>`;

			lastIndex = matchStart + rawToken.length;
			match = pattern.exec(source);
		}

		if (lastIndex < source.length) {
			output += escapeHtml(source.slice(lastIndex));
		}

		return output;
	}

	function detectLanguageFromElement(element) {
		if (!element || !element.className) {
			return "typescript";
		}
		const match = /language-([a-z0-9_-]+)/i.exec(element.className);
		return match ? match[1].toLowerCase() : "typescript";
	}

	function highlightElement(element) {
		if (!element) {
			return;
		}
		const lang = detectLanguageFromElement(element);
		const rawCode = element.textContent || "";
		element.innerHTML = highlight(rawCode, Prism.languages[lang], lang);
	}

	function highlightAll(root) {
		const scope = root || (typeof document !== "undefined" ? document : null);
		if (!scope || typeof scope.querySelectorAll !== "function") {
			return;
		}
		const elements = scope.querySelectorAll("code[class*=\"language-\"], pre[class*=\"language-\"] code");
		elements.forEach(el => highlightElement(el));
	}

	const Prism = {
		manual: true,
		languages: {
			typescript: {},
			rust: {},
			go: {},
			python: {},
			lua: {},
			json: {},
			toml: {},
			bash: {},
			conf: {}
		},
		highlight,
		highlightElement,
		highlightAll
	};

	globalScope.Prism = Prism;

	if (typeof document !== "undefined") {
		if (document.readyState === "loading") {
			document.addEventListener("DOMContentLoaded", () => highlightAll(document));
		} else {
			highlightAll(document);
		}
	}
})(typeof globalThis !== "undefined" ? globalThis : window);
